style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Base background + text */
  body, html {
    background-color: #0b0b0b !important;
    color: #f5f5f5 !important;
  }

  /* Wallpaper effect */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background:
      repeating-linear-gradient(45deg, rgba(255,0,51,0.1) 0 2px, transparent 2px 6px),
      repeating-linear-gradient(-45deg, rgba(57,255,20,0.1) 0 2px, transparent 2px 6px),
      #0b0b0b;
    filter: contrast(1.05) saturate(1.1);
  }

  /* Navigation bar */
  header, .navbar, .rbx-navbar, .nav-container {
    background: #111 !important;
    border-bottom: 2px solid #ff0033 !important;
  }

  /* Links */
  a, .text-link {
    color: #39ff14 !important;
    text-decoration: none !important;
  }
  a:hover, .text-link:hover {
    color: #ff0033 !important;
    text-shadow: 0 0 6px #ff0033 !important;
  }

  /* Cards & Panels */
  .card, .rbx-card, .game-card, .profile-about, .section-content {
    background: #111 !important;
    border: 2px dashed #ff0033 !important;
    border-radius: 6px !important;
    box-shadow: 0 4px 12px rgba(0,0,0,.6) !important;
  }

  /* Buttons */
  button, .btn, .rbx-btn {
    background: #181818 !important;
    border: 2px solid #ff0033 !important;
    color: #f5f5f5 !important;
    font-weight: bold !important;
    text-transform: uppercase !important;
    letter-spacing: 1px !important;
    border-radius: 6px !important;
  }
  button:hover, .btn:hover, .rbx-btn:hover {
    background: #ff0033 !important;
    color: #fff !important;
  }

  /* Inputs */
  input, textarea, select {
    background: #0d0d0d !important;
    border: 2px solid #39ff14 !important;
    color: #f5f5f5 !important;
  }
  input::placeholder, textarea::placeholder {
    color: #aaa !important;
  }

  /* Scrollbar */
  *::-webkit-scrollbar { width: 12px; }
  *::-webkit-scrollbar-thumb {
    background: #ff0033 !important;
    border: 2px solid #0b0b0b !important;
    border-radius: 6px !important;
  }
  *::-webkit-scrollbar-track { background: #0b0b0b !important; }
  * { scrollbar-color: #ff0033 #0b0b0b; scrollbar-width: thin; }
}
